use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = String::new();
    for byte in input.as_bytes() {
        let hex = format!("{:02X}", byte);
        result.push_str(hex);
    }
    result
}

#[cfg(test)]
mod tests {
    use serde_json::Value;

    #[test]
    fn test_solution() {
        let input = serde_json::Value::from(vec![0, 15, 255]);
        let expected = serde_json::Value::from("000fff");
        assert_eq!(solve(input), expected);
    }
}
